ST.xhtml:p:
(*防甩轴1*)
RTring1(CLK := g_biAntiRejection1AbsExecute OR bAntiRejection1AbsExecute OR g_bAntiRejection1AbsExecute);

IF RTring1.Q THEN
  nARAbsState1 := 1;
  g_boAntiRejection1AbsDone := FALSE;
  g_bAntiRejection1AbsDone := FALSE;
  bAntiRejection1AbsDone := FALSE;
  IF g_biAntiRejection1AbsExecute THEN
    dARTargetPos1 := g_fiARTargetPos1; 
    dARTargetVel1 := g_fiARTargetVel1;
  ELSIF bAntiRejection1AbsExecute THEN
    dARTargetPos1 := dARAbsPosition1;
    dARTargetVel1 := 0.0;
  ELSE
    dARTargetPos1 := g_fARAbsPosition1;
    dARTargetVel1 := g_fARAbsVelocity1;
  END_IF;
  IF dARTargetVel1 = 0.0 THEN
    dARTargetVel1 := dARAbsVelocity1;
  END_IF;
END_IF;

IF NOT(g_biAntiRejection1AbsExecute OR bAntiRejection1AbsExecute OR g_bAntiRejection1AbsExecute) THEN
  g_boAntiRejection1AbsDone := FALSE;
  g_bAntiRejection1AbsDone := FALSE;
  bAntiRejection1AbsDone := FALSE;
END_IF;

CASE nARAbsState1 OF
  0:
    nARAbsState1 := 0;
  1:
    g_AntiRejection1Abs.Execute := TRUE;
    g_AntiRejection1Abs.Velocity := dARTargetVel1;
    g_AntiRejection1Abs.Position := dARTargetPos1;
    IF g_AntiRejection1Abs.Done THEN
      g_AntiRejection1Abs.Execute := FALSE;
      g_boAntiRejection1AbsDone := TRUE;
      g_bAntiRejection1AbsDone := TRUE;
      bAntiRejection1AbsDone := TRUE;
      nARAbsState1 := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nARAbsState1 := 20;
    END_IF;
    IF g_AntiRejection1Abs.CommandAborted OR g_AntiRejection1Abs.Error THEN
      g_AntiRejection1Abs.Execute := FALSE;
      bAntiRejection1AbsDone := FALSE;
      nARAbsState1 := 0;
    END_IF;
  20:
    g_AntiRejection1Abs.Execute := FALSE;
    g_AntiRejection1Stop.Execute := TRUE;
    IF g_AntiRejection1Stop.Done AND g_bPlcStartBuffer THEN
      g_AntiRejection1Stop.Execute := FALSE;
      nARAbsState1 := 1;
    END_IF;
    IF g_AntiRejection1Stop.CommandAborted OR g_AntiRejection1Stop.Error THEN
      g_AntiRejection1Stop.Execute := FALSE;
      nARAbsState1 := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nARAbsState1 := 0;
  g_AntiRejection1Abs.Execute := FALSE;
  g_AntiRejection1Stop.Execute := FALSE;
END_IF;
